/* Software-in-the-loop test of HandControl and DisplayDriver (stage D, part 1) on the PC: the Embedded Coder code of both components with
 * the RTE generated by tools/rtegen, stimulated through the RTE buffers (the drivers of neXtBSW IO-117/IO-118 do not exist yet; the
 * test plays the quadrature decoder, the keys and the I2C driver). Description: doc/stufe-d-handbetrieb-anzeige.md.
 * Build and start: test_battsim_sil.py (tests list of the workspace, ci/tests.yaml). */

#include "RteComponents.h"
#include "Rte_Internal.h"

#include <math.h>
#include <stdio.h>
#include <string.h>

static int failures = 0;
static int checks   = 0;

#define CHECK(cond)                                                            \
    do                                                                         \
    {                                                                          \
        ++checks;                                                              \
        if (!(cond))                                                           \
        {                                                                      \
            ++failures;                                                        \
            printf("  FAIL %s:%d: %s\n", __FILE__, __LINE__, #cond);           \
        }                                                                      \
    } while (0)

#define H(name) Rte_Buf_HandControl_##name##_##name
#define D(name) Rte_Buf_DisplayDriver_##name##_##name

static boolean* const keyIn[14] = {&H(CardKey01), &H(CardKey02), &H(CardKey03), &H(CardKey04), &H(CardKey05),
                                   &H(CardKey06), &H(CardKey07), &H(CardKey08), &H(CardKey09), &H(CardKey10),
                                   &H(CardKey11), &H(CardKey12), &H(CardKey13), &H(CardKey14)};

static uint16 voltCounter = 0U;
static uint16 selCounter  = 0U;

static void driverStep(void);

static void cycle(void)
{
    HandTask10ms();
    /* exchange swc -> disp as in the generated RteConfig.cpp (this test runs Rte.c only) */
    Rte_Buf_HandControl_DisplayValue_mV_DisplayValue_mV = Rte_Cpy_swc_HandControl_DisplayValue_mV_DisplayValue_mV;
    Rte_Cpy_disp_HandControl_DisplayValue_mV_DisplayValue_mV = Rte_Buf_HandControl_DisplayValue_mV_DisplayValue_mV;
    DispTask10ms();
    driverStep();
}

static void cycles(int n)
{
    for (int i = 0; i < n; ++i)
    {
        cycle();
    }
}

static void resetInputs(void)
{
    Rte_Buf_BattSimMode_HandActive_HandActive   = 0U;
    H(EncVoltButton) = 0U;
    H(EncSelButton)  = 0U;
    for (int k = 0; k < 14; ++k)
    {
        *keyIn[k] = 0U;
        Rte_Buf_CellChannels_ActualVolt_V_ActualVolt_V[k] = 0.0f;
    }
}

/* counts the encoder delivers (positive = clockwise); one call is one 10 ms step */
static void turnVoltage(int counts)
{
    voltCounter = (uint16)(voltCounter + (uint16)counts);
    H(EncVoltCount) = voltCounter;
    cycle();
}

static void turnSelect(int counts)
{
    selCounter = (uint16)(selCounter + (uint16)counts);
    H(EncSelCount) = selCounter;
    cycle();
}

static void press(boolean* key, int cyclesDown)
{
    *key = 1U;
    cycles(cyclesDown);
    *key = 0U;
    cycles(2);
}

static int near(float32 a, double b)
{
    return fabs((double)a - b) < 1e-5;
}

static int allSetpointsAre(double v)
{
    int ok = 1;
    for (int k = 0; k < 14; ++k)
    {
        ok = ok && near(H(HandSetpoint_V)[k], v);
    }
    return ok;
}

static int allEnableAre(int v)
{
    int ok = 1;
    for (int k = 0; k < 14; ++k)
    {
        ok = ok && ((H(HandEnable)[k] != 0U) == (v != 0));
    }
    return ok;
}

/* ---------------------------------------------------------------------------------------------------------------- */
/* HandControl */

static void startState(void)
{
    cycles(3);
    CHECK(allSetpointsAre(0.0) && allEnableAre(0));
    CHECK(H(SelectedChannel) == 1U && H(SelectAllMode) == 0U && H(DisplayValue_mV) == 0U);
}

static void channelSelection(void)
{
    turnSelect(4); /* one detent = 4 counts */
    CHECK(H(SelectedChannel) == 2U);
    turnSelect(3); /* a part of a detent does nothing ... */
    CHECK(H(SelectedChannel) == 2U);
    turnSelect(1); /* ... and the rest completes it */
    CHECK(H(SelectedChannel) == 3U);
    turnSelect(-8);
    CHECK(H(SelectedChannel) == 1U);
    turnSelect(-4);
    CHECK(H(SelectedChannel) == 1U); /* saturates at 1, does not wrap */
    turnSelect(4 * 40);
    CHECK(H(SelectedChannel) == 14U); /* saturates at 14, not 15 or 16 (F9) */
    turnSelect(-4 * 13);
    CHECK(H(SelectedChannel) == 1U);
    /* the counter wraps over 65535 */
    selCounter = 65532U;
    H(EncSelCount) = selCounter;
    cycles(2);
    CHECK(H(SelectedChannel) == 1U);
    turnSelect(8); /* 65532 -> 4 */
    CHECK(H(SelectedChannel) == 3U);
    turnSelect(-8);
    CHECK(H(SelectedChannel) == 1U);
}

static void voltageEncoderNeedsTheHandMode(void)
{
    turnVoltage(4 * 10);
    CHECK(allSetpointsAre(0.0) && allEnableAre(0)); /* HandActive = 0: nothing happens */
    CHECK(H(SelectedChannel) == 1U);               /* the selection works in every mode */
}

static void handModeStartsAtZeroVolts(void)
{
    Rte_Buf_BattSimMode_HandActive_HandActive = 1U;
    cycles(2);
    CHECK(allSetpointsAre(0.0)); /* F8: 0 V at the start, not the value of the earlier turn */
    CHECK(allEnableAre(1));      /* all channels released */
}

static void voltageEncoderCoarseAndFine(void)
{
    turnVoltage(4 * 10); /* ten detents coarse = 10 * 15 mV on the selected channel 1 */
    CHECK(near(H(HandSetpoint_V)[0], 0.150));
    for (int k = 1; k < 14; ++k)
    {
        CHECK(near(H(HandSetpoint_V)[k], 0.0));
    }
    turnVoltage(-4 * 3);
    CHECK(near(H(HandSetpoint_V)[0], 0.105));
    press(&H(EncVoltButton), 3); /* coarse -> fine */
    turnVoltage(4 * 10);
    CHECK(near(H(HandSetpoint_V)[0], 0.115)); /* 10 * 1 mV */
    turnVoltage(-4 * 200);
    CHECK(near(H(HandSetpoint_V)[0], 0.0)); /* does not go below 0 V */
    press(&H(EncVoltButton), 3);            /* fine -> coarse */
    turnVoltage(4 * 400);
    CHECK(near(H(HandSetpoint_V)[0], 5.0)); /* limited to SetpointLimit_V = 5.0 V */
    turnVoltage(4 * 3);
    CHECK(near(H(HandSetpoint_V)[0], 5.0));
    turnVoltage(-4 * 100);
    CHECK(near(H(HandSetpoint_V)[0], 3.5)); /* 5.0 V - 100 * 15 mV */
}

static void voltageCounterWraps(void)
{
    /* the counter stands at 520 here; 131 detents down bring it to 65532 (over the wrap downwards) */
    turnVoltage(-4 * 131);
    CHECK(voltCounter == 65532U);
    CHECK(near(H(HandSetpoint_V)[0], 3.5 - 131 * 0.015));
    turnVoltage(8); /* 65532 -> 4: two detents up over the wrap */
    CHECK(voltCounter == 4U);
    CHECK(near(H(HandSetpoint_V)[0], 3.5 - 129 * 0.015));
}

static void allChannelsMode(void)
{
    turnSelect(4); /* channel 2 */
    CHECK(H(SelectedChannel) == 2U);
    turnVoltage(4 * 20);
    CHECK(near(H(HandSetpoint_V)[1], 0.300));
    CHECK(near(H(HandSetpoint_V)[0], 3.5 - 129 * 0.015)); /* the other channel stays */
    press(&H(EncSelButton), 3);              /* single -> all */
    CHECK(H(SelectAllMode) == 1U);
    turnVoltage(4);
    CHECK(allSetpointsAre(0.315)); /* the new value of the selected channel for everybody */
    press(&H(EncSelButton), 3);
    CHECK(H(SelectAllMode) == 0U);
    turnVoltage(4);
    CHECK(near(H(HandSetpoint_V)[1], 0.330) && near(H(HandSetpoint_V)[0], 0.315));
}

static void cardKeysToggleTheRelease(void)
{
    CHECK(allEnableAre(1));
    *keyIn[4] = 1U;
    cycles(2);
    CHECK(H(HandEnable)[4] != 0U); /* not yet: debounce 3 cycles */
    cycles(1);
    CHECK(H(HandEnable)[4] == 0U); /* released -> off */
    cycles(20);
    CHECK(H(HandEnable)[4] == 0U); /* held key: no repetition */
    *keyIn[4] = 0U;
    cycles(2);
    press(keyIn[4], 3);
    CHECK(H(HandEnable)[4] != 0U); /* second press: on again */
    press(keyIn[9], 2);            /* a bounce of 2 cycles is no press */
    CHECK(H(HandEnable)[9] != 0U);
    press(keyIn[9], 3);
    CHECK(H(HandEnable)[9] == 0U);
    for (int k = 0; k < 14; ++k)
    {
        CHECK((H(HandEnable)[k] != 0U) == (k != 9));
    }
}

static void leavingTheHandModeClearsAndTheNextEntryStartsAtZero(void)
{
    Rte_Buf_BattSimMode_HandActive_HandActive = 0U;
    cycles(2);
    CHECK(allSetpointsAre(0.0) && allEnableAre(0));
    Rte_Buf_BattSimMode_HandActive_HandActive = 1U;
    cycles(2);
    CHECK(allSetpointsAre(0.0) && allEnableAre(1)); /* also the key 10 is released again */
    CHECK(H(SelectedChannel) == 2U);                /* the selection stays */
    Rte_Buf_BattSimMode_HandActive_HandActive = 0U;
    cycles(2);
}

static void displayValueIsTheSelectedActualValue(void)
{
    Rte_Buf_CellChannels_ActualVolt_V_ActualVolt_V[1] = 4.1234f;
    Rte_Buf_CellChannels_ActualVolt_V_ActualVolt_V[0] = 1.0f;
    cycles(2);
    CHECK(H(SelectedChannel) == 2U && H(DisplayValue_mV) == 4123U);
    turnSelect(-4);
    CHECK(H(DisplayValue_mV) == 1000U);
    Rte_Buf_CellChannels_ActualVolt_V_ActualVolt_V[0] = -0.2f;
    cycles(1);
    CHECK(H(DisplayValue_mV) == 0U);
    Rte_Buf_CellChannels_ActualVolt_V_ActualVolt_V[0] = 12.5f;
    cycles(1);
    CHECK(H(DisplayValue_mV) == 9999U);
    Rte_Buf_CellChannels_ActualVolt_V_ActualVolt_V[0] = 0.0f / 0.0f; /* not a number */
    cycles(1);
    CHECK(H(DisplayValue_mV) == 0U);
    Rte_Buf_CellChannels_ActualVolt_V_ActualVolt_V[0] = 2.0f;
    cycles(1);
    CHECK(H(DisplayValue_mV) == 2000U);
}

/* ---------------------------------------------------------------------------------------------------------------- */
/* DisplayDriver with a model of the I2C driver: it takes an order when DispTxRequest changes and reports it as done after
 * `latency` steps (0 = in the same step), with an error for the order numbers given in failOrder */

static uint8 bytesSent[512];
static int sentCount = 0;
static int latency   = 0;
static int pending   = -1; /* steps until the order in flight is done, -1 = none */
static int failOrder = -1; /* the order with this number (counting from 1 in this test run) fails */
static int orderNo   = 0;
static uint8 seenRequest = 0U;

static void driverModelStart(int newLatency, int newFailOrder)
{
    sentCount   = 0;
    latency     = newLatency;
    pending     = -1;
    failOrder   = newFailOrder;
    orderNo     = 0;
    seenRequest = D(DispTxRequest);
    D(DispTxDone)  = D(DispTxRequest);
    D(DispTxError) = 0U;
}

static void driverStep(void)
{
    if (pending > 0)
    {
        --pending;
    }
    if (pending == 0)
    {
        D(DispTxDone) = seenRequest;
        pending       = -1;
    }
    if (D(DispTxRequest) != seenRequest)
    {
        CHECK((uint8)(D(DispTxRequest) - seenRequest) == 1U); /* never two orders at once */
        seenRequest = D(DispTxRequest);
        ++orderNo;
        if (sentCount < 512)
        {
            bytesSent[sentCount++] = D(DispTxByte);
        }
        D(DispTxError) = (orderNo == failOrder) ? 1U : 0U;
        if (latency == 0)
        {
            D(DispTxDone) = seenRequest;
        }
        else
        {
            pending = latency;
        }
    }
}

static int pictureIs(const uint8* b, int hasClear, int mv)
{
    int i  = 0;
    int ok = 1;
    if (hasClear)
    {
        ok = ok && (b[i++] == 0x76U);
    }
    const int digit[4] = {(mv / 1000) % 10, (mv / 100) % 10, (mv / 10) % 10, mv % 10};
    for (int k = 0; k < 4; ++k)
    {
        ok = ok && (b[i++] == 0x79U) && (b[i++] == (uint8)k) && (b[i++] == (uint8)digit[k]);
    }
    ok = ok && (b[i++] == 0x77U) && (b[i++] == 0x01U);
    return ok;
}

static void setDisplayedValue(int mv)
{
    Rte_Buf_BattSimMode_HandActive_HandActive      = 0U;
    Rte_Buf_CellChannels_ActualVolt_V_ActualVolt_V[0] = (float32)mv / 1000.0f;
    cycles(1);
}

/* shows a value, waits until the picture is complete, then restarts the model of the driver */
static void settle(int mv, int newLatency, int newFailOrder)
{
    setDisplayedValue(mv);
    cycles(60);
    driverModelStart(newLatency, newFailOrder);
}

static void firstPictureHasAClear(void)
{
    cycles(30);
    CHECK(sentCount == 15); /* clear, 4 * (cursor, position, digit), decimal control and mask; then quiet */
    CHECK(pictureIs(bytesSent, 1, 0)); /* value 0: "0.000" */
}

static void noNewPictureWithoutChangeUntilTheRefresh(void)
{
    turnSelect(-4 * 20); /* channel 1 */
    settle(4123, 0, -1);
    cycles(40);
    CHECK(sentCount == 0);
    cycles(70); /* more than DisplayRefresh_cycles = 100 since the picture */
    CHECK(sentCount == 14);
    CHECK(pictureIs(bytesSent, 0, 4123)); /* the same picture, without a clear */
}

static void aChangeStartsANewPicture(void)
{
    settle(4123, 0, -1);
    setDisplayedValue(2501);
    cycles(30);
    CHECK(sentCount == 14);
    CHECK(pictureIs(bytesSent, 0, 2501));
    driverModelStart(0, -1);
    setDisplayedValue(15000); /* 15 V: limited to 9999 */
    cycles(30);
    CHECK(sentCount == 14);
    CHECK(pictureIs(bytesSent, 0, 9999));
}

static void aSlowDriverGetsOneByteAtATime(void)
{
    settle(1, 3, -1); /* every order is done 3 steps after it was taken */
    setDisplayedValue(3333);
    cycles(100);
    CHECK(sentCount == 14);
    CHECK(pictureIs(bytesSent, 0, 3333));
}

static void aFailedOrderRestartsThePictureWithAClear(void)
{
    settle(1111, 0, 5); /* the fifth order of the next picture fails */
    setDisplayedValue(2222);
    cycles(10);
    CHECK(sentCount == 5); /* the picture stops at the failed order ... */
    cycles(30);
    CHECK(sentCount == 5); /* ... and the pause (DisplayRetry_cycles = 50) is not over */
    cycles(40);
    CHECK(sentCount == 5 + 15); /* then a whole picture with a clear follows */
    CHECK(pictureIs(bytesSent + 5, 1, 2222));
    cycles(60);
    CHECK(sentCount == 5 + 15);
}

/* 0.5.4: the order counter wraps (255 -> 0). With the saturating counter of 0.5.3 no order was taken after the 255th byte and the
 * display froze; 25 pictures of 14 bytes are 350 orders. */
static void theOrderCounterWrapsAndThePicturesKeepComing(void)
{
    settle(1, 0, -1);
    uint8 const startRequest = D(DispTxRequest);
    int expected = 0;
    for (int i = 0; i < 25; ++i)
    {
        int const mv = 1000 + (i * 37);
        setDisplayedValue(mv);
        cycles(25);
        expected += 14;
        CHECK(sentCount == expected);
        CHECK(pictureIs(bytesSent + expected - 14, 0, mv));
    }
    CHECK(orderNo == 350);
    CHECK(D(DispTxRequest) == (uint8)(startRequest + orderNo)); /* 350 orders: the counter went round at least once */
}

static void theChainFromTheSelectedChannelToTheDisplay(void)
{
    settle(1, 1, -1);
    turnSelect(4 * 5); /* channel 6 */
    Rte_Buf_CellChannels_ActualVolt_V_ActualVolt_V[5] = 3.7f;
    cycles(60);
    CHECK(H(SelectedChannel) == 6U && H(DisplayValue_mV) == 3700U);
    CHECK(sentCount >= 14);
    CHECK(pictureIs(bytesSent + sentCount - 14, 0, 3700));
}

int main(void)
{
    HandControl_Init(); /* the initial states of the persistent variables of the models */
    DisplayDriver_Init();
    resetInputs();
    driverModelStart(0, -1);
    startState();
    firstPictureHasAClear();
    channelSelection();
    voltageEncoderNeedsTheHandMode();
    handModeStartsAtZeroVolts();
    voltageEncoderCoarseAndFine();
    voltageCounterWraps();
    allChannelsMode();
    cardKeysToggleTheRelease();
    leavingTheHandModeClearsAndTheNextEntryStartsAtZero();
    displayValueIsTheSelectedActualValue();
    noNewPictureWithoutChangeUntilTheRefresh();
    aChangeStartsANewPicture();
    aSlowDriverGetsOneByteAtATime();
    aFailedOrderRestartsThePictureWithAClear();
    theOrderCounterWrapsAndThePicturesKeepComing();
    theChainFromTheSelectedChannelToTheDisplay();
    printf("%d checks, %d failures\n", checks, failures);
    return (failures == 0) ? 0 : 1;
}
